                content: `
### Архитектура эстрального цикла
Репродуктивная физиология самок хоботных (Loxodonta africana и Elephas maximus) кардинально отличается от других наземных млекопитающих. Эстральный цикл слоних является самым продолжительным среди всех сухопутных животных и составляет **14–16 недель** (в среднем 112–116 дней).

**Фолликулярная фаза (4–6 недель):**
Характеризуется уникальным двухволновым выбросом лютеинизирующего гормона (ЛГ):

1. Первый волна (anLH — Anovulatory LH peak): Происходит на 1–2 неделе фолликулярной фазы. Выброс ЛГ стимулирует рост фолликулов и индуцирует вокальные и поведенческие проявления эструса (Estrous Walk, Estrous Rumble), но **не приводит к овуляции**.

2. Вторая волна (ovLH — Ovulatory LH peak): Происходит ровно через **21 день (3 недели)** после первого пика. Именно этот второй выброс ЛГ вызывает истинную овуляцию доминантного фолликула и формирование желтого тела.

**Лютеиновая фаза (8–12 недель):**
Характеризуется высокой секрецией прогестагенов (преимущественно 5α-прегнанов, таких как 5α-прегнан-3,20-дион), поддерживающих готовность эндометрия к имплантации.
                `
