                content: `
### Акушерская патология и вмешательство
Дистоция (осложненные роды) у слоних в неволе часто связана со слабой родовой деятельностью (атонией матки), гиподинамией, крупноплодием или неправильным предлежанием.

**Консервативная стимуляция Окситоцином:**
* Условие применения: Применение питоцина/окситоцина разрешено **только при полном раскрытии шейки матки** и правильном головном или тазовом предлежании.
* Дозирование: **20–40 МЕ внутримышечно (IM)** или медленно капельно внутривенно под контролем ультрасонографии.

**Хирургическое решение (Вестибулотомия):**
Из-за глубокого залегания брюшины и многотонной массы органа классическое кесарево сечение у слонов имеет крайне высокий процент летальности. При невозможности эвакуации плода выполняется **эпизиотомия / вестибулотомия** — хирургический рассек дорсальной стенки преддверия влагалища.

[CLINICAL GUIDANCE]
**Критическое правило:**
Окситоцин разрешён ТОЛЬКО при полном раскрытии шейки матки и правильном предлежании! Применение при неполном раскрытии или неправильном предлежании вызывает разрыв матки и гибель матери.
                `
