                content: `
### Beehive Fences (Метод Люси Кинг и Фрица Фольрата)
Разработанный Люси Кинг (Lucy King) и Фрицем Фольратом (Fritz Vollrath) метод биодетерренции основан на эволюционном страхе слонов перед укусами медоносных пчел (Apis mellifera) в чувствительные зоны (глаза, внутреннюю поверхность хобота и заушные области).

**Конструктивный регламент:**
Деревянные ульи или ульи-пустышки подвешиваются по периметру полей на высоте 1.5–1.8 м с интервалом 10 метров и соединяются между собой стальной проволочной растяжкой.

**Дистанционный эффект роя:**
При попытке слона проникнуть на поле задевание проволоки раскачивает ульи, провоцируя вылет пчел. Всплеск инфразвукового рокота тревоги («Bee Panic Rumble») побуждает даже не задевших изгородь особей разворачиваться и покидать территорию в радиусе до 100 метров.

**Эффективность:**
Пчелиные изгороди предотвращают от 80% до 86% попыток вторжения слонов, одновременно обеспечивая местным общинам дополнительный доход от продажи «слонобезопасного меда» (Elephant-Friendly Honey).
                `
