                content: `### Танатологический этограмм Elephantidae (McComb 2006, Douglas-Hamilton 2006)
Хоботные — одни из немногих млекопитающих (наряду с человеком и шимпанзе), демонстрирующих специфический, высокоорганизованный поведенческий комплекс в отношении погибших сородичей и их останков.

* **Избирательный интерес к костям (*McComb et al., 2006*):** В контролируемых экспериментах с предъявлением черепов слонов, буйволов и носорогов, африканские слоны демонстрировали статистически значимый избирательный интерес именно к черепам и бивням собственного вида.
* **Модальность обследования:** Животные приближаются в тишине, пальпируют останки пальцевидным отростком хобота, обследуют зубные альвеолы и бивни, осторожно раскачивают кости стопой.
* **Траурное бдение (*Mourning Guard*):** При гибели членов семьи (особенно матриарха) стадо остаётся около тела в течение **3–7 дней**. Локомоция группы парализуется, слоны отгоняют хищников-падальщиков и покрывают тело срезанными ветками, дерном и землей.

\`\`\`
 Избирательный интерес к черепам/бивням ──► Тактильная пальпация хоботом и стопой
                                                         │
                                                         ▼
 Покрытие тела ветками/землей ──► Многодневное бдение (3–7 дней) + Защита от хищников
\`\`\``
