                content: `### Классификация эмпатических актов (Bates, Lee & Byrne, 2008)
На основе анализа 255 документированных наблюдений в национальном парке Амбосели (Кения) Люси Бейтс и коллеги выделили 5 категорий когнитивной эмпатии у слонов:

1. **Защита (*Protection*):** Упреждающее заслоняющее поведение взрослых самок, защищающих детенышей от падения в промоины, атак хищников или увязания в грязи до возникновения сигнала бедствия.
2. **Утешение (*Consolation*):** Тактильный контакт *«хобот к рту»* (*trunk-to-mouth*) или *«хобот к височной железе»*, сопровождаемый тихим аффилиативным рокотом в адрес особи, перенесшей испуг или социальную агрессию.
3. **Помощь в передвижении (*Assisting Mobility*):** Физическая поддержка ослабленных или травмированных сородичей с помощью бивней и хобота (подведение бивней под грудь и подмышечные впадины).
4. **Удаление посторонних предметов (*Removing Foreign Objects*):** Извлечение хоботом и зубами транквилизаторных дротиков, копий или ветеринарных игл из тела сородича.
5. **Предотвращение увода (*Retrieval*):** Извлечение и защита детенышей при попытках чужих семейных групп увести калфа.

| Категория эмпатии | Физическое проявление | Когнитивная атрибуция | Авторы / Источники |
| :--- | :--- | :--- | :--- |
| **Consolation** | Trunk-to-mouth контакт, успокаивающий рокот | Атрибуция эмоции и стресса сородича | Plotnik & de Waal, 2014 |
| **Assisting Mobility** | Поднимание бивнями, подпора телом | Атрибуция физической некомпетентности | Bates et al., 2008 |
| **Removing Objects** | Вытаскивание дротиков/копей | Атрибуция вредоносности объекта | Bates & Byrne, 2007 |`
