                content: `### Экология питания и стратегия толстокишечной ферментации
Слоны относятся к категории **нежвачных травоядных с толстокишечной ферментацией (*Hindgut Fermenters*)**. Суточное потребление сухой биомассы взрослым слоном составляет **1.5–2.5% от массы тела** (от 150 до 300 кг влажного корма в сутки).

* **Градиент Browse vs Graze:**
  * *Азиатский слон (Elephas maximus):* До **60–85% рациона** составляет травянистая растительность (злаки, бамбук, осока).
  * *Саванный слон (Loxodonta africana):* Пластичный смешанный тип питания — сезонный переход от злаков во влажный период к веткам, коре и корням деревьев (*browse*) в сухой сезон.
  * *Лесной слон (Loxodonta cyclotis):* До **40–50% рациона** составляют плоды тропических деревьев (высокая степень фруктоедения / фагофилии).
* **Физиологический КПД переваривания:** Из-за быстрого транзита корма через ЖКТ (**24–45 часов**) усвояемость клетчатки составляет всего **30–45%** (против 60–70% у жвачных). Стратегия слона базируется не на глубоком усвоении, а на обработке колоссального объема биомассы.

    Потребление 150–300 кг корма/сутки ──► Быстрый транзит ЖКТ (24–45 ч)
                                                     │
                                                     ▼
    Усвоение клетчатки 30–45% ──► Постоянный поток растительной массы через слепую кишку`
