                content: `### Концепция Keystone Species и аллогенный инжиниринг
Хоботные классифицируются как ключевые (**keystone species**) и аллогенные инженеры экосистем (*allogenic ecosystem engineers*) — организмы, чье механическое воздействие радикально преобразует физическую структуру среды обитания.

* **Механизм трансформации вегетации:** Валя деревья, обдирая кору (*debarking*) и выкорчевывая кустарники, слоны предотвращают превращение мозаичных саванн в сплошные непроходимые заросли (*bush encroachment*).
* **Формирование микробиотопов:** Поваленные слонами крупные деревья создают защитные убежища от инсоляции и крупных хищников для мелких млекопитающих, рептилий и затененных травянистых растений.
* **Поддержание световых окон в тропических лесах:** В дождевых лесах Конго и Юго-Восточной Азии проходы лесных слонов (*Loxodonta cyclotis*) формируют коридоры освещенности, стимулирующие возобновление яруса подлеска.

\`\`\`
  Сваливание деревьев и дебаркинг ──► Предотвращение bush encroachment
                                                   │
                                                   ▼
   Создание световых окон в лесу ──► Формирование мозаичных микробиотопов
\`\`\``
