                content: `### Гидроинженерия, микроводоемы и детерренция Beehive Fences
* **Гидрологическое бурение:** В сухой сезон слоны раскапывают песчаные русла пересохших рек бивнями и хоботом на глубину до **1.0–1.5 метра**, открывая доступ к чистым грунтовым водам для десятков видов птиц и копытных.
* **Микроводоемы в следах:** Глубокие отпечатки стоп слонов в плотном грунте во влажный период накапливают до **0.5–1.0 литра воды**, формируя уникальные микробиотопы для размножения земноводных и водных насекомых.
* **Экскавация солонцов:** В пещерах (например, гора Элгон) слоны отбивают бивнями и поедают богатые натрием вулканические породы, расширяя пещерные комплексы.

[CLINICAL GUIDANCE]
**Протокол гуманного предотвращения конфликтов (Beehive Fences):**
Для защиты сельскохозяйственных угодий от набегов слонов используется система «пчелиных заборов» (King et al., 2011). Слоны испытывают аверсивный страх перед укусами африканских медоносных пчел в области чувствительного хобота и глаз; акустический сигнал гула роя пчел вызывает немедленное отступление стада без применения насилия.`
