                content: `### Судебно-генетическая революция в борьбе с браконьерством
Крупномасштабные изъятия нелегальной слоновой кости (*ivory seizures*) объемом по 3–5 тонн в международных морских портах долгое время не позволяли установить точное место отстрела животных. Прорыв связан с разработкой методов криминалистической экстракции ДНК из дентина бивней судебно-генетической группой Сэмюэля Вассера (*Samuel Wasser et al.*).

* **Анатомический субстрат ДНК:** Живые одонтобласты находятся лишь в пульпарной камере у основания бивня, тогда как основное тело бивня состоит из плотного кальцинированного матрикса дентина. Экстракция ДНК требует соскабливания внутреннего слоя дентина пульпарной полости и деминерализации порошка раствором ЭДТА (*EDTA*).
* **Создание пан-африканской референсной карты:** Исследователи собрали и генотипировали **653 образца свежего навоза из 28 стран Африки** по панели из **16 высокополиморфных тетрануклеотидных микросателлитных (STR) локусов**, создав сплошную географическую карту частот аллелей.

\`\`\`
 Соскабливание дентина пульпарной полости ──► Деминерализация порошка ЭДТА
                                                             │
                                                             ▼
 Генотипирование по 16 STR-локусам ──► Сравнение с пан-африканской картой навоза
\`\`\``
