                content: `### Гребенчатый рельеф зубов и эволюционный ряд мамутид
Семейство **Mammutidae** («настоящие мастодонты», миоцен — поздний плейстоцен) развивалось параллельно линии Elephantidae, сохранив приспособленность к питанию мягкой лесной веточной растительностью (*browsing*).

1. **Зиголофодонтный тип моляров (*Zygolophodonty*):** Поперечные гребни зубов превращены в острые эмалевые «крыши» (*yoke-like crests*) без центральных бугорков и без забивания цементом промежуточных долин. Зуб работал как набор острых ножниц для измельчения хвои, веток и коры.
2. **Эволюционная линия Mammutidae:**
   * *Eozygodon / Zygolophodon (миоцен):* Сохраняли умеренную трилофодонтию и мелкие нижние бивни.
   * *Mammut borsoni (плиоцен Евразии):* Обладал рекордными прямыми верхними бивнями длиной до **5.02 метров**.
   * *Mammut americanum (Американский мастодонт, плейстоцен):* Терминальный вид с массивным приземистым скелетом (высота до 3.0 м, масса до 8 тонн) и густой шерстью, заселивший болотно-таежные леса Северной Америки.

| Анатомический признак | Deinotheriidae (Deinotherium) | Mammutidae (Mammut americanum) | Elephantidae (Mammuthus / Elephas) |
| :--- | :--- | :--- | :--- |
| **Бивни (Tusks)** | Только нижние (изогнуты вниз) | Только верхние (изогнуты вверх) | Только верхние (изогнуты спирально) |
| **Смена зубов** | Вертикальная (все зубы сразу) | Горизонтальная (зубной конвейер) | Горизонтальная (зубной конвейер) |
| **Рельеф моляров** | Простая дилофодонтия | Зиголофодонтия (острые гребни) | Ламеллярная гипсодонтия (пластины) |
| **Экологическая ниша** | Лесной консервативный браузер | Хвойно-лесной браузер | Степной / саванный гразер ($C_4$) |`
