                content: `### Программа мониторинга незаконного отстрела слонов (MIKE)
Для объективного контроля смертности слонов на десятках контрольных площадок в Африке и Азии CITES учредила программу **MIKE (*Monitoring the Illegal Killing of Elephants*)**.

1. **Метрика PIKE (*Proportion of Illegally Killed Elephants*):**
   * Основной количественный показатель браконьерского пресса, вычисляемый как отношение числа туш незаконно убитых слонов к общему количеству обнаруженных туш:
   $$\\text{PIKE} = \\frac{N_{\\text{незаконно убитые}}}{N_{\\text{всего туш (естественная смертность + браконьерство)}}}$$
2. **Критический порог устойчивости ($\text{PIKE} = 0.50$):**
   * При $\\text{PIKE} > 0.50$ браконьерская смертность превышает естественный темп воспроизводства популяции (прирост ~5% в год), заставляя популяцию стремительно сокращаться.
   * В пик браконьерского кризиса 2011 года показатель PIKE в Центральной Африке достигал **0.80–0.90**.
3. **База данных ETIS (*Elephant Trade Information System*):** Реестр всех мировых изъятий контрабандной кости, отслеживающий маршруты транснациональных криминальных синдикатов.

| Индикатор CITES | Описание и назначение | Критическое значение | Экологический статус |
| :--- | :--- | :--- | :--- |
| **PIKE < 0.50** | Браконьерство ниже темпа естественного прироста | Безопасная зона | Популяция растет или стабильна |
| **PIKE = 0.50** | Порог нулевого популяционного баланса | Нулевой прирост | Популяция на грани падения |
| **PIKE > 0.50** | Браконьерство превышает рождаемость | **КРАСНАЯ ЗОНА** | Популяция неуклонно сокращается |`
