                content: `### Пространственная экология мегагербиворов и геоинформационные методы
Пространственная активность слонов (*Elephantidae*) диктуется распределением водных ресурсов, высококалорийных кормовых макропачей, сезонной динамикой растительности и избеганием антропогенного прессинга.

* **Метод минимального выпуклого полигона (Minimum Convex Polygon, MCP):** Исторический метод построения внешнего контура ареала по крайним точкам локализаций. Ограничением MCP является включение неиспользуемых антропогенных зон и водоемов.
* **Ядерная оценка плотности (Kernel Density Estimation, KDE):**
  * *95% KDE:* Отражает общий **домашний ареал (*Home Range*)**, охватывающий сезонные перемещения.
  * *50% KDE:* Фиксирует **ядро ареала (*Core Area*)**, состоящее из ключевых водопоев, минеральных солонцов (*bais*) и отдыха.
* **Суточные сдвиги активности (Gaynor et al., 2018):** В условиях фрагментации слоны демонстрируют временное разделение ресурсов (*diel activity shift*), пересекая антропогенные зоны и дороги исключительно в ночное время.

\`\`\`
   GPS/GSM-телеметрия ──► Построение вероятностных контуров KDE
                                       │
                                       ▼
  50% KDE (Ключевые ядра: водопои/солонцы) vs 95% KDE (Общий сезонный ареал)
\`\`\``
