                content: `### Ландшафтное сопротивление и алгоритмы связности (Circuitscape)
Сплошное расчленение природных ареалов автодорогами, каналами и огороженными частными землями (*group ranches*) создает угрозу изоляции популяций.

1. **Карта ландшафтного сопротивления (*Cost Surface / Friction Map*):** Присвоение каждому пикселю ландшафта индекса сопротивления движению на основе уклона рельефа, плотности дорог, автотрафика и близости к поселениям.
2. **Алгоритм пути наименьшего сопротивления (*Least-Cost Path, LCP*):** Вычисляет оптимальный пространственный маршрут с минимальными энергетическими и стрессовыми затратами для животных между защищенными ООПТ.
3. **Теория электрических цепей (*Circuit Theory / Circuitscape*):** Моделирует альтернативные диффузные пути миграции, выявляя узкие «бутылочные горлышки» (*chokepoints*), требующие срочного выкупа или оформления защитных сервитутов.

| Пространственный алгоритм | Входные параметры | Выходной результат | Прикладное значение |
| :--- | :--- | :--- | :--- |
| **Minimum Convex Polygon (MCP)** | Точки GPS-локализаций | Общий внешний контур | Первичная оценка максимального охвата |
| **Kernel Density Estimation (KDE)** | Плотность GPS-точек в пространстве | Изолинии 50% и 95% вероятности | Выделение критических ядер биотопа |
| **Least-Cost Path (LCP)** | Карта фрикций (Cost Surface) | Линейный тракт с мин. сопротивлением | Проектирование физических экокоридоров |
| **Circuit Theory (Circuitscape)** | Топография + Сопротивление | Карта токов и узких мест (*chokepoints*) | Оценка гибкости миграционной сети |`
