                content: `### Практика перемещения диких слонов (Fernando et al., 2012; Pinter-Wollman et al., 2009)
Транслокация — принудительный отлов и перевозка особей — применяется как крайняя мера при разрешении HEC или для генетического спасения (*Genetic Rescue*) изолированных популяций.

* **Ветеринарный протокол иммобилизации:** Использование мощных морфиномиметиков (эторфин / тиафентанил) в комбинации с седативными (азаперон / ксилазин) с немедленным введением антагонистов (дипренорфин / налтрексон) после погрузки в транспортные контейнеры.
* **Правило сохранения семейных групп:** Категорически запрещается отлавливать и перевозить членов одной семьи по отдельности. Разрыв социальных связей вызывает тяжелый посттравматический стрессовый синдром (*ПТСР*), гиперагрессию и высокую смертность.
* **Неэффективность индивидуальной транслокации быков-деструкторов:** Исследования Прабакара Фернандо (*Fernando et al., 2012*) доказали, что одиночные самцы-фуражиры, переселенные на расстояние 100–200 км, либо совершают обратный марш в натальный ареал (*homing behavior*), либо начинают разрушать поселения на новом месте.

[FIELD GUIDANCE]
**Протокол проведения транслокации слонов:**
Транслокация должна планироваться только на уровне всей матрилинейной семьи. Перед выпуском группы в новом заповеднике необходима организация предварительной адаптации в мягких вольерах (*boma*), а также постоянный GPS-мониторинг для контроля хоминга и адаптации к местным водопоям.`
