                content: `### Мозаичная трансформация ландшафтов и архитектура световых окон
Слоны (*Elephantidae*) являются классическими **экосистемными инженерами (*Ecosystem Engineers*)** и **ключевыми видами (*Keystone Species*)**, чья жизнедеятельность определяет структуру и функционирование целых биоценозов.

* **Трансформация лесов в саванны (*Bush Clearing / Tree Felling*):** Поедая ветви, сдирая кору и валя деревья, слоны предотвращают зарастание саванн сплошным древесным ярусом. Это создает мозаичный ландшафт с преобладанием богатых $C_4$-злаковых лугов.
* **Формирование световых окон (*Canopy Gaps*):** В тропических лесах (бассейн Конго, Юго-Восточная Азия) повал гигантских деревьев образует прогалины в пологе леса, открывая солнечный свет для подроста молодняка.
* **Создание микробиотопов:** Поврежденные стволы, дупла и глубокие следы от стоп слонов наполняются водой, превращаясь в микрорефугиумы для размножения земноводных, ящериц, моллюсков и бесзвоночных.

\`\`\`
   Повал деревьев и сдирание коры ──► Открытие полога леса (Canopy Gaps)
                                                │
                                                ▼
   Рост $C_4$-злакового яруса + Формирование микроводоемов в следах ──► Высокое биоразнообразие
\`\`\``
