                content: `### Слоны как ключевые мегафаунальные распространители семян (Campos-Arceiz & Blake, 2011)
Слоны являются эффективнейшими мегафаунальными вектором дальнего распространения семян (**эндозоохории**) в тропических экосистемах.

1. **Дальность переноса (до 50–100+ км):** Ввиду длительного транзита корма через ЖКТ (от 24 до 45 часов) и протяженных суточных переходов семена переносятся на рекордные расстояния, обеспечивая генетический поток между изолированными микропопуляциями растений.
2. **Механико-химическая скарификация:** Кислая среда желудка и ферменты кишечника размягчают плотную деревянистую оболочку крупносемянных плодов (*Balanites maughamii*, *Sclerocarya birrea* / марула, *Panda oleosa*), повышая прорастаемость семян в **3–10 раз**.
3. **Навоз как питательный субстрат:** Каловые массы слона обеспечивают семена влагой, азотом и фосфором, защищая проростки от высыхания и обеспечивая естественный биокомпост.

| Экологический процесс | Механизм действия | Экологический эффект | Последствия утери слонов |
| :--- | :--- | :--- | :--- |
| **Эндозоохория** | Проглатывание плодов и перенос семян | Дальний рассев семян (до 100 км) | Прекращение генетического обмена растений |
| **Скарификация** | Обработка желудочным соком в ЖКТ | Увеличение всхожести семян в 3–10 раз | Затухание возобновления ценных пород деревьев |
| **Ландшафтный повал** | Выкорчевывание деревьев бивнями | Формирование мозаики саванн | Зарастание саванн монокультурным кустарником |`
