                content: `### Создание водных оазисов и трагический эффект экстирпации
* **Гидробурение в сухих руслах (*Sand River Digging*):** В сухой сезон слоны выкапывают бивнями и стопами гидравлические ямы (до 1–2 метров глубиной) в песчаных руслах пересохших рек (*sand rivers*), открывая доступ к линзам грунтовых вод. Этими ямами затем пользуются десятки видов животных (антилопы, зебры, хищники, птицы).
* **Минеральная геофагия (*Geophagy*):** Слоны отламывают и поедают натрий- и кальцийсодержащие пласты глин в солонцах (*bais*), обогащая минералами не только свой организм, но и разгружая соль в навозе по всему лесу.
* **Синдром распада экосистемы (*Ecosystem Breakdown Syndrome*):**
  Исчезновение (экстирпация) слонов приводит к деградации биоценоза:
  1. Исчезают крупносемянные деревья, зависимые от эндозоохории.
  2. Саванны зарастают густым непроходимым кустарником (*bush encroachment*), вытесняя травоядных мезогербиворов (зебр, газелей).
  3. В сухой сезон массово гибнут мелкие виды из-за отсутствия выкопанных слонами гидравлических ям.

[FIELD GUIDANCE]
**Критерий статуса Keystone Species:**
Исчезновение слонов из экосистемы запускает каскадное вымирание десятков видов флоры и фауны. При оценке биоразнообразия охраняемых территорий слон рассматривается как "зонтичный вид" (*Umbrella Species*), защита которого автоматически сохраняет весь ландшафтный комплекс.`
